<script setup lang="ts">
import {ref,onMounted,reactive} from 'vue'
import {command,message} from '../api'
import {useAuth} from '../stores/auth'
import {useDatabase} from '../stores/database'
import PageHeading from '../components/PageHeading.vue'
interface Account{id:number;username:string;name:string;role:string;doctorId:number|null;enabled:number;revision:number}
const auth=useAuth(),db=useDatabase(),users=ref<Account[]>([]),error=ref(''),busy=ref(false),show=ref(false),doctorShow=ref(false),doctorName=ref('')
const form=reactive({id:null as number|null,revision:null as number|null,username:'',name:'',role:'viewer',doctorId:undefined as number|undefined,enabled:true,password:'',confirmation:''})
const roles=[{label:'Администратор',value:'admin'},{label:'Врач',value:'doctor'},{label:'Только просмотр',value:'viewer'}]
async function load(){try{users.value=await command('list_users');await db.load()}catch(e){error.value=message(e)}}
function edit(user?:Account){Object.assign(form,{id:null,revision:null,username:'',name:'',role:'viewer',doctorId:undefined,enabled:true,password:'',confirmation:''},user?{...user,doctorId:user.doctorId||undefined,enabled:Boolean(user.enabled)}:{});error.value='';show.value=true}
async function save(){busy.value=true;error.value='';try{if(form.password!==form.confirmation)throw Error('Пароли не совпадают');await command('save_user',{input:{...form,doctorId:form.doctorId??null,password:form.password||null}});show.value=false;await load();if(form.id===auth.user?.id)await auth.init()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function addDoctor(){busy.value=true;try{await command('save_doctor',{name:doctorName.value});doctorShow.value=false;doctorName.value='';await db.load()}catch(e){error.value=message(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="page-content"><PageHeading title="Пользователи" description="Пароли и права доступа к локальной программе"><UButton variant="outline" icon="i-lucide-stethoscope" @click="doctorShow=true">Добавить врача</UButton><UButton icon="i-lucide-user-plus" @click="edit()">Новый пользователь</UButton></PageHeading><UAlert v-if="error&&!show" color="error" variant="soft" :description="error" class="mb-5"/><div class="table-panel"><div class="table-scroll"><table class="patient-table"><thead><tr><th>Пользователь</th><th>Логин</th><th>Роль</th><th>Статус</th><th>Действие</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td>{{user.name}}</td><td>{{user.username}}</td><td>{{roles.find(r=>r.value===user.role)?.label}}</td><td>{{user.enabled?'Активен':'Отключён'}}</td><td><UButton variant="ghost" @click="edit(user)">Изменить</UButton></td></tr></tbody></table></div></div><p class="mt-6 text-slate-600">Врач может изменять только исследования, оформленные от своего имени. Пользователь с доступом «Только просмотр» не может менять записи. Резервные копии, восстановление и управление пользователями доступны администратору.</p><UModal v-model:open="show" :title="form.id?'Изменить учётную запись':'Новый пользователь'" description="Изменение пароля завершит прежний сеанс пользователя" :ui="{content:'max-w-[640px]',body:'p-7 sm:p-7'}"><template #body><form id="user-form" @submit.prevent="save" class="space-y-6"><UAlert v-if="error" color="error" variant="soft" :description="error"/><UFormField label="Имя"><UInput v-model="form.name" required class="w-full"/></UFormField><UFormField label="Логин" description="Латинские буквы, цифры, точка, дефис, подчёркивание"><UInput v-model="form.username" required minlength="3" autocomplete="off" class="w-full"/></UFormField><UFormField label="Роль"><USelect v-model="form.role" :items="roles" class="w-full"/></UFormField><UFormField v-if="form.role==='doctor'" label="Врач в протоколах"><USelect v-model="form.doctorId" :items="db.info?.doctors.map(d=>({label:d.name,value:d.id}))||[]" placeholder="Выберите врача" class="w-full"/></UFormField><UCheckbox v-model="form.enabled" label="Учётная запись активна"/><UFormField :label="form.id?'Новый пароль — оставьте пустым, чтобы сохранить прежний':'Пароль'" description="Не менее 10 символов"><UInput v-model="form.password" type="password" :required="!form.id" :minlength="form.password?10:undefined" autocomplete="new-password" class="w-full"/></UFormField><UFormField label="Повторите новый пароль"><UInput v-model="form.confirmation" type="password" :required="Boolean(form.password)" autocomplete="new-password" class="w-full"/></UFormField></form></template><template #footer><UButton color="neutral" variant="ghost" @click="show=false">Отмена</UButton><UButton type="submit" form="user-form" :loading="busy">Сохранить</UButton></template></UModal><UModal v-model:open="doctorShow" title="Добавить врача" description="Имя будет доступно при оформлении исследований"><template #body><form id="doctor-form" @submit.prevent="addDoctor"><UFormField label="Фамилия и инициалы"><UInput v-model="doctorName" required class="w-full"/></UFormField></form></template><template #footer><UButton color="neutral" variant="ghost" @click="doctorShow=false">Отмена</UButton><UButton type="submit" form="doctor-form" :loading="busy">Добавить</UButton></template></UModal></section></template>
